import { DEFAULT_THEME, normalizeTheme } from './styles/theme.js';
import {CUMULATIVE_PROMPT_FIELDS,cumulativePromptDefault} from '../shared/settings/cumulative-prompts.js';
import {cumulativeEscape as esc,cumulativeButton as button,cumulativeIcon as icon,mountCumulativeSurface} from './cumulative-view.js';
export function cumulativeSettingsMarkup(state,theme=DEFAULT_THEME){const disabled=state.status!=='ready',fields=CUMULATIVE_PROMPT_FIELDS.map(({key,name})=>`<details class="lt-summary-prompt ui-disclosure" data-cu-open="${key}"><summary><span class="lt-summary-label"><span class="lt-summary-label-text">${name}</span></span></summary><div class="lt-summary-prompt-body lt-stack"><textarea class="lt-textarea" rows="9" aria-label="${name}" data-cu-field="prompt:${key}" ${disabled?'disabled':''}>${esc(state.promptDrafts[key]??state.draft?.promptOverrides?.[key]??cumulativePromptDefault(key))}</textarea><div class="lt-summary-editor-actions">${button('恢复默认',`default:${key}`,disabled)}${button('取消',`cancel:${key}`,disabled)}${button('保存',`save:${key}`,disabled,'primary')}</div></div></details>`).join('');
  return `<section class="lantai lt-summary-settings ui-workspace ui-graphic-controls" data-ui-theme="${normalizeTheme(theme)}"><header class="lt-header ui-header ui-header--centered">${icon('back','返回古法记忆','back')}<h1 class="ui-page-title">总结设置</h1>${icon('close','关闭兰台本末','close')}</header><main class="lt-main lt-summary-settings-main ui-main ui-main--settings" tabindex="-1"><p class="lt-error" role="alert" ${state.error?'':'hidden'}>${esc(state.message)}</p><section class="lt-summary-section"><h2>总结内容</h2><div class="lt-summary-panel lt-summary-content-panel"><div class="lt-stack"><h3 class="ui-field__label">不参与总结的楼层</h3><div class="lt-tags">${state.excludedFloors.map(item=>{const floor=typeof item==='number'?item:item.floor;return `<span class="ui-tag">${floor}${button('×',`remove-floor:${floor}`,disabled,'tertiary',`aria-label="移除第${floor}楼排除"`)}</span>`;}).join('')}</div><div class="lt-entry"><input class="ui-input" type="number" min="0" step="1" inputmode="numeric" aria-label="排除楼层" data-cu-field="floor" value="${esc(state.floorDraft)}" ${disabled?'disabled':''}>${button('添加','add-floor',disabled)}</div></div><div class="lt-summary-divider"><button type="button" class="ui-button ui-button--tertiary ui-row lt-summary-link" data-cu-action="cleaning" ${disabled?'disabled':''}><span>总结文本清洗</span><span aria-hidden="true">›</span></button></div></div></section><section class="lt-summary-section"><h2>总结提示词</h2><div class="lt-summary-prompt-group ui-disclosure">${fields}</div></section><section class="lt-summary-section"><h2>注入</h2><label class="ui-field"><span class="ui-field__label">记忆注入深度</span><input class="ui-input" type="number" min="0" step="1" inputmode="numeric" data-cu-field="injection" value="${esc(state.injectionDraft??state.draft?.injectionPosition??9999)}" ${disabled?'disabled':''}></label>${button('保存','save-injection',disabled,'primary')}</section>${state.status==='unconfirmed'||state.status==='error'?button('重新读取','read'):''}</main><p class="lt-saved lt-status" role="status" hidden>已保存</p></section>`;
}
export function mountCumulativeSettingsView({container,controller}={}){let last=controller.inspect().savedSequence,timer=null;const view=mountCumulativeSurface({container,controller,scope:()=> 'cumulative-settings',markup:cumulativeSettingsMarkup,input(node){const field=node.dataset.cuField;if(field?.startsWith('prompt:'))controller.editPrompt(field.slice(7),node.value);if(field==='injection')controller.editInjection(node.value);if(field==='floor')controller.setFloorDraft(node.value);},async click(action){if(action==='back')controller.back();if(action==='close')controller.close();if(action==='cleaning')controller.openCleaning();if(action==='add-floor')await controller.addFloor(controller.inspect().floorDraft);if(action.startsWith('remove-floor:'))await controller.removeFloor(action.slice(13));if(action.startsWith('default:')){controller.restorePrompt(action.slice(8));view.render();}if(action.startsWith('cancel:'))controller.cancelPrompt(action.slice(7));if(action.startsWith('save:')){const key=action.slice(5);if(!Object.hasOwn(controller.inspect().promptDrafts,key)){const state=controller.inspect();controller.editPrompt(key,state.draft?.promptOverrides?.[key]??cumulativePromptDefault(key));}await controller.savePrompt(key);}if(action==='save-injection')await controller.saveInjection();if(action==='read')await controller.read();}});
  const off=controller.subscribe(state=>{if(state.savedSequence===last)return;last=state.savedSequence;const toast=container.querySelector('.lt-saved');if(toast)toast.hidden=false;clearTimeout(timer);timer=setTimeout(()=>{const toast=container.querySelector('.lt-saved');if(toast)toast.hidden=true;},2000);});return {dispose(){clearTimeout(timer);off();view.dispose();}};
}
